const $=s=>document.querySelector(s),canvas=$('canvas'),sceneCtx=canvas.getContext('2d'),panel=$('#panel'),content=$('#content');
let ctx=sceneCtx;const actorLayer=document.createElement('canvas');actorLayer.width=1000;actorLayer.height=600;actorLayer.className='actor-layer';actorLayer.setAttribute('aria-hidden','true');$('#stage').append(actorLayer);const actorCtx=actorLayer.getContext('2d');
let saved={};try{saved=JSON.parse(localStorage.getItem('jacc-v1')||'{}')}catch{}
