$('#close').onclick=close;panel.addEventListener('close',()=>{if('speechSynthesis'in window)speechSynthesis.cancel()});
function card(item){open(item.name);paragraph(item.icon,'illustration');paragraph(item.diagram,'diagram');paragraph(item.text);button('🔊 Listen',()=>{if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(item.text);u.volume=state.settings.volume;speechSynthesis.cancel();speechSynthesis.speak(u)}});button('↻ Replay',()=>{chime();speak(item.text);const d=content.querySelector('.diagram');d.textContent=item.diagram;d.style.background='#fff0b8'});button('📍 Revisit',()=>{close();select(objects.find(o=>o.id===item.id)||objects.find(o=>o.find===item.id)||objects.find(o=>o.id==='dig'))});if(item.id==='hq-map')button('🌱 Go exploring',()=>{close();select(objects.find(o=>o.id==='hq-exit'))});if(item.id==='hq-lab')button('⛏️ Find a sample',()=>{close();select(objects.find(o=>o.id==='dig'))});if(item.id==='hq-bunks')button('☾ Rest here',()=>{close();state.paused=true;$('#pause').innerHTML='▶ <span>Resume</span>';announce('Resting. Tap Resume whenever you are ready.');});if(materials.some(m=>m.id===item.id))button('🤖 Ask PIP',()=>showPipAnalysis(item.id));speak(item.text);}
function discover(item){if(materials.some(m=>m.id===item.id))state.visited.add('dig');state.discoveries.add(item.id);persist();chime();announce('Discovered: '+item.name);card(item)}
function interact(o){state.last=o.id;if(o.kind!=='dig')state.visited.add(o.id);persist();if(o.kind==='portal'){const next=state.journey;changeZone(o.to);if(next)select(objects.find(x=>x.id===next));return}if(o.kind==='diglevel'){setDigLevel(o.nextLevel);return}if(o.kind==='digtools'){showDigLesson('tools');return}if(o.kind==='diglesson'){showDigLesson(o.lesson);return}if(o.kind==='digfind'){discover(digFinds.find(f=>f.id===o.find));return}if(o.kind==='engineering'){showEngineering(o.project);return}if(o.kind==='farm'){showFarm(o.page);return}if(o.kind==='workshop'){pipWorkshop();return}if(o.kind==='crew'){crewMenu();return}if(o.kind==='home'){announce('Welcome home to the training grounds. Choose any adventure.');return}if(o.kind==='dig'){state.action='dig';state.timer=state.settings.reduced?.25:1.3;announce('Digging through the soil…');return}discover(o)}
function start(){if(state.started)return;state.started=true;scenes.enter('grounds');$('#begin').hidden=true;announce('Tap a place or a picture to explore. PIP can show you how.');chime();}
function activeObjects(){return objects.filter(o=>o.zone===state.zone&&(state.zone!=='dig'||digVisible(state.excavation,o)))}
function changeZone(id){state.zone=id;if(id==='dig'){state.excavation.level=0;state.excavation.path=[];state.excavation.target=null;}[state.x,state.y]=zones[id].spawn;state.path=[];state.pending=null;state.action=null;state.journey=null;state.ring=null;renderTargets();$('#zone-label').textContent=zones[id].name;canvas.setAttribute('aria-label',zones[id].name+'. Use the destination buttons to explore.');announce('Welcome to '+zones[id].name+'.');}
function select(o){if(!o)return;start();if(state.paused){announce('Tap Resume to keep exploring.');return}state.journey=null;if(o.zone!==state.zone){state.journey=o.id;o=objects.find(x=>x.id===zoneExit(state.zone,o.zone))}if(state.zone==='dig'){if(o.level!==state.excavation.level)setDigLevel(o.level);selectDigPoint(o.x,o.y,o.id);return}state.action=null;state.ring={x:o.x,y:o.y};state.pending=o;state.path=pathfind([state.x,state.y],[o.x-65,o.y+55],state.zone);announce('Going to '+o.name);if(!state.path.length){state.pending=null;const here=cellAt(state.x,state.y),goal=cellAt(o.x-65,o.y+55);if(here.join()===goal.join()&&!blocked(...goal,state.zone))interact(o);else{state.journey=null;announce('Choose a clear path to explore.');}}}
function renderTargets(){$('#targets').replaceChildren();for(const o of activeObjects()){const b=button(o.icon+' ',()=>select(o),$('#targets'));b.className='target';b.dataset.id=o.id;b.style.left=o.x/10+'%';b.style.top=o.y/6+'%';b.setAttribute('aria-label',o.name);const label=document.createElement('small');label.textContent=o.name;b.append(label)}}
renderTargets();
$('#begin').onclick=start;
canvas.addEventListener('pointerdown',e=>{if(panel.open||state.paused)return;start();const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*1000/r.width,y=(e.clientY-r.top)*600/r.height;if(state.zone==='dig'){selectDigPoint(x,y);return}if(blocked(...cellAt(x,y),state.zone)){announce(state.zone==='hq'?'That is a wall or furniture. Tap an open path.':'The pond is water. Tap the path around it.');state.ring={x,y};return}state.path=pathfind([state.x,state.y],[x,y],state.zone);state.journey=null;state.pending=null;state.action=null;state.ring={x,y};announce('Walking to your marker.');});
$('#pause').onclick=()=>{state.paused=!state.paused;$('#pause').innerHTML=state.paused?'▶ <span>Resume</span>':'Ⅱ <span>Pause</span>';announce(state.paused?'Paused. Take your time.':'Ready to explore.');if(state.paused&&'speechSynthesis'in window)speechSynthesis.cancel()};
function setDigLevel(level){state.excavation.level=level;state.excavation.path=[];state.excavation.target=null;state.x=180;state.y=180;state.path=[];renderTargets();persist();announce(level?'Deep cavern observation area.':'Upper excavation site.');}
function selectDigPoint(x,y,target=null){if(state.paused)return;const cell=digCell(x,y);if(digBlocked(...cell,state.excavation.level)){showDigLesson('magma');return}state.path=[];state.pending=null;state.ring={x:cell[0]*40+20,y:cell[1]*40+20};beginDig(state.excavation,[state.x,state.y],[x,y],target);announce(characters.active[0]==='Aiden Williams'?'Aiden is using his heavy digging rig.':'Digging automatically. PIP helps with hard formations.');}
function showDigLesson(page){const v=digView(state.excavation,page,roster.indexOf(characters.active));open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.innerHTML=digArt(v.art,state.excavation);art.className='farm-art';const p=document.createElement('p');p.textContent=v.text;info.append(art,p);content.append(info);const buttons=document.createElement('div');buttons.className='farm-choices';content.append(buttons);for(const a of v.actions)button(a.label,()=>{if(a.type==='reset'){state.excavation.cleared[state.excavation.level]=[];setDigLevel(state.excavation.level);close();}else if(a.type==='tool'){state.excavation.tool=a.value;persist();announce(a.label+' fitted.');close()}else if(a.type==='hints'){state.excavation.hints=true;renderTargets();persist();close()}else{state.excavation[a.type]=1-(state.excavation[a.type]||0);showDigLesson(page)}},buttons);button('🔊 Listen',()=>readJournal(v.text));paragraph('Supported training tunnels and cutaway models. Not to scale.');}
function showEngineering(project,page=0){const v=designView(project,state.discoveries,state.designs[project]);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const a=document.createElement('div');a.className='farm-art';a.innerHTML=engineeringArt(project);const p=document.createElement('p');p.textContent=v.text;info.append(a,p);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const f of v.samples.slice(page*3,page*3+3))button((v.selected===f.id?'✓ ':'')+f.icon+' Use '+f.name,()=>{state.designs[project]=f.id;persist();showEngineering(project,page)},choices);if(!v.samples.length)button('⛏️ Find samples',()=>{close();select(objects.find(o=>o.id==='grounds-dig'))},choices);if(v.selected)button('🌱 Install on farm',()=>{state.farm.upgrades[project]=v.selected;persist();close();select(objects.find(o=>o.id===designFarmTarget(project)))},choices);if(page>0)button('← Previous',()=>showEngineering(project,page-1),choices);if(v.samples.length>(page+1)*3)button('Next →',()=>showEngineering(project,page+1),choices);button('🔊 Listen',()=>readJournal(v.text));paragraph('Reusable samples. No materials are spent. Selected: '+(v.selected||'none yet'));}
function updateDig(dt){const r=tickDig(state.excavation,[state.x,state.y],dt,roster.indexOf(characters.active));[state.x,state.y]=r.position;if(r.changed){persist();renderTargets();}const arrived=objects.find(o=>o.id===r.arrived);if(r.found&&!state.discoveries.has(r.found)&&arrived?.find!==r.found)discover(digFinds.find(f=>f.id===r.found));if(arrived)interact(arrived);}
function drawDig(){rect(0,0,1000,600,'#203440');ctx.fillStyle='#eff3df';ctx.font='bold 21px system-ui';ctx.fillText(state.excavation.level?'DEEP CAVERNS • observe gently':'DIG SITE • tap ground to excavate',35,75);for(let y=4;y<=12;y++)for(let x=1;x<=23;x++){const lava=digBlocked(x,y,state.excavation.level),solid=digSolid(state.excavation,x,y);rect(x*40,y*40,39,39,lava?'#e79856':solid?(digHard(x,y)?'#66616e':y<=6?'#b59a73':y<=8?'#9c7c68':'#77717b'):'#283f4b');if(!solid&&!lava&&state.excavation.cleared[state.excavation.level].includes(x+','+y)){rect(x*40+8,y*40+30,24,3,'#b8a47a');rect(x*40+8,y*40+8,3,25,'#b8a47a');rect(x*40+29,y*40+8,3,25,'#b8a47a');}}ctx.fillStyle='#eef4df';ctx.font='16px system-ui';ctx.fillText('Automatic excavation • support lifts • PIP help • no failure states',40,560);}
function drawEngineering(){rect(0,0,1000,600,'#ceded4');rect(0,0,1000,100,'#203f4d');ctx.fillStyle='#eff3df';ctx.font='bold 24px system-ui';ctx.fillText('ENGINEERING & TERRAFORMING MODELS',35,60);for(const [x,y]of [[300,240],[650,240],[650,430]]){rect(x-100,y-60,200,110,'#9ab8b2');rect(x-80,y-40,160,70,'#e8edd9');}}
function showFarm(route='home',message=''){const v=farmView(state.farm,route);open(v.title);panel.classList.add('farm-panel');const info=document.createElement('div');info.className='farm-info';const art=document.createElement('div');art.className='farm-art';art.innerHTML=farmArt(farmArtKey(state.farm,route));art.setAttribute('role','img');art.setAttribute('aria-label',v.visual);const text=document.createElement('p');text.textContent=v.body;info.append(art,text);content.append(info);const choices=document.createElement('div');choices.className='farm-choices';content.append(choices);for(const a of v.actions){const b=button(a.label,()=>{const result=farmAction(state.farm,a.action);state.farm=result.farm;persist();if(result.travel){close();select(objects.find(o=>o.id===result.travel))}else{chime();showFarm(result.route,result.message)}},choices);b.dataset.farmAction=a.action.type;if(a.action.id)b.dataset.plant=a.action.id;}const footer=document.createElement('div');footer.className='journal-controls';content.append(footer);button('🔊 Listen',()=>readJournal(v.title+'. '+v.body),footer);button('🗺️ Explore farm',()=>{close();if(state.zone!=='farm')select(objects.find(o=>o.id==='farm-garden'))},footer);paragraph(message||'Simple science models. Pictures are not to scale.','farm-message');}
function journalEntries(section){return getJournalEntries(section,state.discoveries,state.visited,objects,materials,state.farm)}
function readJournal(message){if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(message);u.volume=state.settings.volume;u.rate=.85;speechSynthesis.speak(u)}}
function journalHome(){open('My Journal');panel.classList.add('journal-panel');paragraph('My stories. My discoveries. My adventures.','journal-intro');const grid=document.createElement('div');grid.className='journal-grid';content.append(grid);for(const section of journalSections){const b=button('',()=>journalPage(section.id),grid);b.dataset.section=section.id;const picture=document.createElement('span');picture.className='journal-icon';picture.textContent=section.icon;picture.setAttribute('aria-hidden','true');const title=document.createElement('span');title.textContent=section.title;b.append(picture,title);}button('🔊 Listen',()=>readJournal('My journal. Choose what I did, what I discovered, my adventures, my experiments, or my minerals.'));}
function journalPage(id,page=0){const section=journalSections.find(s=>s.id===id),entries=journalEntries(id);open(section.title);panel.classList.add('journal-panel');paragraph(section.intro,'journal-intro');const chunk=entries.slice(page*4,page*4+4);if(!entries.length){paragraph(section.icon,'illustration');paragraph(section.empty,'journal-empty');button('📍 Explore',()=>{close();select(objects.find(o=>o.id===section.target))});}const grid=document.createElement('div');grid.className='journal-grid journal-entries';content.append(grid);for(const entry of chunk){const b=button(entry.icon+' '+entry.title,()=>journalDetail(entry,id,page),grid);b.dataset.entry=entry.id;}const controls=document.createElement('div');controls.className='journal-controls';content.append(controls);button('← My Journal',journalHome,controls);if(page>0)button('← Previous',()=>journalPage(id,page-1),controls);if(entries.length>(page+1)*4)button('Next →',()=>journalPage(id,page+1),controls);button('🔊 Listen',()=>readJournal(section.title+'. '+(entries.length?chunk.map(e=>e.summary).join(' '):section.empty)),controls);}
function journalDetail(entry,section,page){open(entry.title);panel.classList.add('journal-panel');paragraph(entry.icon,'illustration');paragraph(entry.summary,'journal-intro');paragraph(entry.fact,'journal-fact');const controls=document.createElement('div');controls.className='journal-controls';content.append(controls);button('🔊 Listen',()=>readJournal(entry.summary+' '+entry.fact),controls);button('↻ Do It Again',()=>{close();select(objects.find(o=>o.id===entry.target))},controls);button('← '+journalSections.find(s=>s.id===section).title,()=>journalPage(section,page),controls);}
$('#journal').onclick=journalHome;
function crewMenu(){open('Choose your J.A.C.C. crew');panel.classList.add('crew-panel');paragraph('One tap selects your astronaut. Everyone can explore every activity.');const grid=document.createElement('div');grid.className='crew-grid';content.append(grid);for(const r of roster){const selected=characters.active[0]===r[0];const b=button('',()=>{characters.select(r[0]);persist();updateCrew();close();announce(r[0]+' selected. '+r[2]);speak(r[0]+'. '+r[2])},grid);b.className='crew-card';b.setAttribute('aria-label',r[0]+', '+r[1]+' suit. '+r[2]);b.setAttribute('aria-pressed',String(selected));const icon=document.createElement('span');icon.className='crew-portrait';icon.style.setProperty('--suit',suitColors[r[1]]);icon.setAttribute('aria-hidden','true');const name=document.createElement('strong');name.textContent=r[0];const detail=document.createElement('small');detail.textContent=r[1]+' • '+r[2];const badge=document.createElement('span');badge.textContent=selected?'✓ Selected':'Select';b.append(icon,name,detail,badge);}paragraph('Temporary suit-color placeholders. Approved character artwork will replace these.');}
function updateCrew(){document.querySelector('#active-crew').textContent=characters.active[0]+' • '+characters.active[1]+' suit';$('#crew').setAttribute('aria-label','Choose astronaut. Current: '+characters.active[0]);}
$('#crew').onclick=crewMenu;updateCrew();
function pipHelp(){open('PIP • Your exploration helper');paragraph('🤖 → 👆 → ⛏️','illustration');button('✨ Show places',()=>{close();if(state.zone==='dig'){state.excavation.hints=true;renderTargets();}document.querySelectorAll('.target').forEach(b=>b.classList.add('hint'));announce('The bright pictures are places you can explore.');});button('▶ Show me a dig',()=>{close();select(objects.find(o=>o.id==='dig'))});button('↩ Previous activity',()=>{close();select(objects.find(o=>o.id===state.last)||objects.find(o=>o.id===zones[state.zone].home))});button('🔊 Repeat guidance',()=>{announce('Tap a picture. Your astronaut walks there and explores. Tap the pickaxe to dig.');speak('Tap a picture. Your astronaut walks there and explores. Tap the pickaxe to dig.')});button('🏠 Return home',()=>{close();select(objects.find(o=>o.id===zones[state.zone].home))});button('🛠 Build PIP',pipWorkshop);button('🔎 Analyze a discovery',pipDiscoveries)};
$('#pip').onclick=pipHelp;
function pipWorkshop(){open('PIP Workshop');panel.classList.add('pip-panel');mountPipWorkshop({root:content,config:state.pip,crewIndex:()=>roster.indexOf(characters.active),onChange:c=>{state.pip=c;persist();chime()},onDone:()=>{close();announce('PIP is ready to explore with '+characters.active[0]+'.')},onAnalyze:pipDiscoveries,onHelp:pipHelp,onSpeak:readJournal});}
function pipDiscoveries(){open('Ask PIP');paragraph('Choose something I discovered.');const found=materials.filter(m=>state.discoveries.has(m.id));if(!found.length){paragraph('Dig to find our first sample.');button('⛏️ Go digging',()=>{close();select(objects.find(o=>o.id==='dig'))})}for(const m of found)button(m.icon+' '+m.name,()=>showPipAnalysis(m.id));button('← PIP Workshop',pipWorkshop);}
function showPipAnalysis(id){const a=pipAnalysis(id,state.pip.tool);if(!a)return;open('PIP investigates: '+a.title);panel.classList.add('pip-panel');paragraph(a.detail,'journal-intro');paragraph(a.formula,'diagram');const atoms=document.createElement('div');atoms.className='pip-atoms';atoms.setAttribute('aria-label','Illustrated formula pattern');for(const [symbol,name,count]of a.atoms){const group=document.createElement('div');group.className='pip-atom-group';for(let i=0;i<count;i++){const atom=document.createElement('span');atom.className='pip-atom';atom.textContent=symbol;atom.setAttribute('aria-hidden','true');group.append(atom)}const label=document.createElement('p');label.textContent=name+' × '+count;group.append(label);atoms.append(group)}content.append(atoms);paragraph(a.note,'journal-fact');paragraph('PIP uses our science guide. This is a simple model of the formula.');button('🔊 Listen',()=>readJournal(a.detail+' '+a.note));button('← My samples',pipDiscoveries);button('🛠 PIP Workshop',pipWorkshop);}
let pipImageKey='',pipImage=null;
function drawPipBuddy(x,y){const key=JSON.stringify(state.pip);if(key!==pipImageKey){pipImageKey=key;pipImage=new Image();pipImage.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(pipSvg(state.pip));}if(pipImage?.complete&&pipImage.naturalWidth)ctx.drawImage(pipImage,x,y,70,70);}
$('#settings').onclick=()=>{open('Accessibility & sound');const volume=document.createElement('label');volume.textContent='🔊 Volume';const range=document.createElement('input');range.type='range';range.min=0;range.max=1;range.step=.1;range.value=state.settings.volume;range.setAttribute('aria-label','Sound volume');range.oninput=()=>{state.settings.volume=+range.value;persist()};volume.append(range);content.append(volume);for(const [key,label] of [['narration','🔊 Optional narration'],['reduced','🐢 Reduced animation'],['effects','✨ Visual effects']]){const l=document.createElement('label'),i=document.createElement('input');i.type='checkbox';i.checked=state.settings[key];i.onchange=()=>{state.settings[key]=i.checked;persist()};l.append(i,document.createTextNode(label));content.append(l)}paragraph('All activities wait for you. No dragging, fast tapping, scores, or penalties.');};
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h)}
function drawPlan(plan){for(const p of plan){ctx.fillStyle=p.color;if(p.kind==='rect')ctx.fillRect(p.x,p.y,p.w,p.h);else if(p.kind==='ellipse'){ctx.beginPath();ctx.ellipse(p.x,p.y,p.w,p.h,0,0,Math.PI*2);ctx.fill()}else{ctx.font='bold '+p.size+'px system-ui';ctx.fillText(p.text,p.x,p.y)}}}
function drawHQ(){drawPlan(hqPlan);ctx.fillStyle='#eff8f5';ctx.font='bold 26px system-ui';ctx.fillText('GSEI HQ',40,60);}
function draw(t){ctx=sceneCtx;ctx.clearRect(0,0,1000,600);if(state.zone==='dig')drawDig();else if(state.zone==='engineering')drawEngineering();else if(state.zone==='hq')drawHQ();else if(state.zone==='farm'){drawPlan(farmPlan);if(state.farm.upgrades.water)rect(570,325,100,10,'#407c9b');if(state.farm.upgrades.habitat)rect(355,200,110,10,'#407c9b');if(state.farm.upgrades.bridge)rect(120,335,120,10,'#407c9b');}else{rect(0,0,1000,600,'#b7d98d');rect(0,0,1000,90,'#a5deeb');ctx.fillStyle='#8ab96e';ctx.beginPath();ctx.ellipse(350,200,200,110,0,0,7);ctx.fill();ctx.strokeStyle='#e8cc94';ctx.lineWidth=70;ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(130,460);ctx.lineTo(290,460);ctx.lineTo(450,420);ctx.lineTo(730,420);ctx.lineTo(830,480);ctx.stroke();ctx.lineWidth=46;ctx.beginPath();ctx.moveTo(290,460);ctx.lineTo(220,245);ctx.lineTo(380,175);ctx.lineTo(500,110);ctx.lineTo(740,110);ctx.lineTo(815,180);ctx.lineTo(710,410);ctx.stroke();rect(520,160,160,160,'#4b9fb6');for(let y=185;y<310;y+=35)rect(540,y,110,5,'#95d5df');rect(735,135,180,100,'#8e6b55');rect(735,125,180,85,'#c6a17c');for(let i=0;i<5;i++)rect(735,220+i*16,150-i*22,13,'#ddbf91');rect(395,440,120,20,'#bd8b60');rect(395,460,120,15,'#986644');rect(395,475,120,12,'#71482f');ctx.fillStyle='#285344';ctx.font='bold 21px system-ui';ctx.fillText('GSEI • DISCOVERY TRAINING GROUNDS',35,46);ctx.font='16px system-ui';ctx.fillText('↖ Hill trail',280,105);ctx.fillText('Auto-climb ramp ↗',745,325);ctx.fillText('HOME HUB • HQ ←   •   PLANET FARM →',55,565);}
if(state.ring){ctx.strokeStyle=state.settings.effects?'#fff8b2':'#1a3547';ctx.lineWidth=5;ctx.beginPath();ctx.arc(state.ring.x,state.ring.y,25,0,7);ctx.stroke()}
actorCtx.clearRect(0,0,1000,600);ctx=actorCtx;const x=state.x,y=state.y,bob=(state.path.length||(state.zone==='dig'&&state.excavation.path.length))&&!state.settings.reduced?Math.sin(t/90)*3:0;ctx.fillStyle='#0003';ctx.beginPath();ctx.ellipse(x,y+20,20,7,0,0,7);ctx.fill();rect(x-16,y-15+bob,32,34,suitColors[characters.active[1]]);rect(x-12,y+16+bob,9,12,'#23384f');rect(x+4,y+16+bob,9,12,'#23384f');rect(x-19,y-42+bob,38,29,'#f5f4e4');rect(x-13,y-35+bob,26,15,'#28495e');rect(x-25,y-10+bob,8,22,'#e3e5cf');rect(x+17,y-10+bob,8,22,'#e3e5cf');if(state.zone==='dig'&&characters.active[0]==='Aiden Williams'){rect(x+16,y-15,22,12,'#edc74d');rect(x+36,y-13,12,8,'#a0bdc5');}if(state.action==='dig'){ctx.font='30px system-ui';ctx.fillText('⛏️',x+18,y)}drawPipBuddy(x-85,y-80);if(state.zone==='dig'&&state.excavation.path.length){rect(x-38,y-42,22,8,'#9db5bf');}ctx=sceneCtx;}
let prev=performance.now();function loop(t){const dt=Math.min((t-prev)/1000,.05);prev=t;if(state.started&&!state.paused&&!panel.open){if(state.zone==='dig')updateDig(dt);else if(state.path.length){const p=state.path[0],dx=p[0]-state.x,dy=p[1]-state.y,d=Math.hypot(dx,dy),step=150*dt;if(d<=step){[state.x,state.y]=p;state.path.shift();if(!state.path.length&&state.pending){const o=state.pending;state.pending=null;interact(o)}}else{state.x+=dx/d*step;state.y+=dy/d*step}}if(state.action){state.timer-=dt;if(state.timer<=0){state.action=null;discover(materials[state.dug++%materials.length])}}}draw(state.paused?0:t);requestAnimationFrame(loop)}requestAnimationFrame(loop);
